# The calculator from the board: one function per grammar level.
#   E -> T ( ( + | - ) T )*
#   T -> F ( ( * | / ) F )*
#   F -> ( E ) | number
class Parser:
    def __init__(self, text):
        self.text = text.replace(" ", "")
        self.pos = 0

    def peek(self):
        if self.pos < len(self.text):
            return self.text[self.pos]
        return None

    def match(self, char):
        if self.peek() == char:
            self.pos += 1
            return True
        return False

    def E(self):
        value = self.T()
        while self.peek() in ("+", "-"):
            op = self.peek()
            self.match(op)
            right = self.T()
            value = value + right if op == "+" else value - right
        return value

    def T(self):
        value = self.F()
        while self.peek() in ("*", "/"):
            op = self.peek()
            self.match(op)
            right = self.F()
            value = value * right if op == "*" else value / right
        return value

    def F(self):
        if self.match("("):
            value = self.E()
            self.match(")")
            return value
        number = ""
        while self.peek() is not None and self.peek().isdigit():
            digit = self.peek()
            number += digit
            self.match(digit)
        return int(number)


for text in ["2 + 3 * 4", "(2 + 3) * 4", "7 - 2 - 1"]:
    print(text, "=", Parser(text).E())
